(function(){
  if(window.__k20BasketRuntimeRepairV1){return;}
  window.__k20BasketRuntimeRepairV1=true;
  function el(id){return document.getElementById(id);}
  function numFrom(id){var node=el(id);if(!node){return 0;}var t=(node.textContent||'').replace(/[۰-۹]/g,function(d){return'۰۱۲۳۴۵۶۷۸۹'.indexOf(d);}).replace(/[^0-9.]/g,'');return parseFloat(t)||0;}
  function fa(n){return new Intl.NumberFormat('fa-IR',{maximumFractionDigits:0}).format(n||0);}
  function productById(id){var data=(window.K20TapeBasketData||{}).products||{};var keys=Object.keys(data);for(var i=0;i<keys.length;i++){if(String(data[keys[i]].id)===String(id)){return data[keys[i]];}}return null;}
  function card(p,qty,note){if(!p){return '';}var stock=p.stock==='instock'?'موجود':'ناموجود/نیازمند استعلام';var price=p.price_html?' — '+p.price_html:'';return '<article class="tc-product-card"><strong>'+p.name+'</strong><p>تعداد برآوردی: <b>'+fa(qty)+'</b></p><p>'+stock+price+'</p>'+(note?'<small>'+note+'</small>':'')+'<p><a class="tc-btn tc-btn-secondary" href="'+p.url+'">مشاهده محصول</a></p></article>';}
  function build(){var root=el('k20-basket-items');var data=window.K20TapeBasketData;if(!root){return;}if(!data){setTimeout(build,300);return;}var products=data.products||{};var rolls=Math.max(1,Math.ceil(numFrom('tc-result-rolls')));var starts=Math.max(1,Math.ceil(numFrom('tc-result-start-fittings')));var ends=Math.max(1,Math.ceil(numFrom('tc-result-end-fittings')));var tapeNode=el('k20-basket-tape');var tapeKey=tapeNode?tapeNode.value:'tape_open_20';if(!tapeKey){tapeKey='tape_open_20';}var tape=products[tapeKey]||products.tape_open_20||products.tape_plastic_20||null;var startNode=el('k20-basket-start');var startId=startNode?startNode.value:'none';var start=startId==='none'?null:productById(startId);var joiner=products.tape_to_tape||null;var html='';html+=card(tape,rolls,'تعداد رول از خروجی محاسبه‌گر خوانده شده است.');if(start){html+=card(start,starts,'نوع اتصال شروع را شما انتخاب کرده‌اید؛ تعداد از تعداد خطوط + ذخیره محاسبه‌گر می‌آید.');}if(joiner){html+=card(joiner,Math.max(1,Math.ceil(starts*.03)),'ذخیره پیشنهادی اولیه برای تعمیر/اتصال؛ در پروژه واقعی با روش اجرا تطبیق دهید.');}root.innerHTML=html;var summary='سبد برآوردی کشاورز بیست\n'+(tape?tape.name+': '+fa(rolls)+' رول\n':'')+(start?start.name+': '+fa(starts)+' عدد\n':'')+(joiner?joiner.name+': '+fa(Math.max(1,Math.ceil(starts*.03)))+' عدد\n':'')+'قطعات انتهایی موردنیاز طبق محاسبه‌گر: '+fa(ends)+' عدد\n\nفرضیات: تعدادها از محاسبه‌گر همین صفحه گرفته شده‌اند. فیلتر، لوله اصلی و ابزار پانچ بدون داده پروژه به‌صورت خودکار انتخاب نشده‌اند.';window.K20BasketSummary=summary;var wa=el('k20-basket-whatsapp');if(wa){wa.href='https://wa.me/'+data.whatsapp+'?text='+encodeURIComponent('سلام. برای بررسی و پیش‌فاکتور این سبد آبیاری کمک می‌خواهم:\n\n'+summary);}}
  function copy(){build();var text=window.K20BasketSummary||'';if(!text){return;}var done=function(){var b=el('k20-basket-copy');if(!b){return;}var old=b.textContent;b.textContent='سبد کپی شد';setTimeout(function(){b.textContent=old;},1400);};if(navigator.clipboard){if(navigator.clipboard.writeText){navigator.clipboard.writeText(text).then(done);return;}}var ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();done();}
  function bind(){var root=el('k20-basket-items');if(!root){return;}var r=el('k20-basket-refresh');var c=el('k20-basket-copy');var t=el('k20-basket-tape');var s=el('k20-basket-start');if(r){r.addEventListener('click',build);}if(c){c.addEventListener('click',copy);}if(t){t.addEventListener('change',build);}if(s){s.addEventListener('change',build);}var calc=el('tc-calculate');if(calc){calc.addEventListener('click',function(){setTimeout(build,0);});}build();setTimeout(build,400);}
  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',bind,{once:true});}else{bind();}
})();
var mc=(document.modelContext)||(window.navigator ? window.navigator.modelContext : null);
